/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Clearing an assignee publishes `issue.unassigned`
 * (and only when someone was actually assigned). Moving the issue from one
 * person to another stays `issue.assigned`.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    if (before.assigneeId !== null) {
      await emit("issue.unassigned", {
        ...actorEnvelope(actor),
        issueId: after.id,
        projectId: after.projectId,
        previousAssigneeId: before.assigneeId,
      });
    }
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

/** Live issues currently assigned to `assigneeId`. Archived rows stay out. */
export async function listLiveIssuesByAssignee(
  orgId: OrgId,
  assigneeId: UserId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.assigneeId, assigneeId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .all();

  return rows.map((row) => toIssue(row));
}

